import pandas as pd
def clean(df):
    df["body_mass_g"] = pd.to_numeric(df["body_mass_g"], errors='coerce')
    df = df[(df["body_mass_g"] >= 2500) & (df["body_mass_g"] <= 6500)]
    return df
def answer(df):
    grouped = df.groupby('species')["body_mass_g"].sum().reset_index()
    result = {}
    for _, row in grouped.iterrows():
        species = row['species']
        total = row['body_mass_g']
        result[species] = total
    return result
